  "parts": [
    {
      "kind": "campus_fact",
      "text": "Counseling Services (Counseling Center) can be reached by phone at (201) 684-7522 and by email at studentwellness@ramapo.edu; their office is listed as D-216 on campus.",
      "evidence_ids": [
        "contacts:b690fd0c-fc57-492a-a6ad-0d6f4a658df5",
        "documents:d76a6749-bc33-41bb-b060-6393861f78d9"
      ]
    },
    {
      "kind": "campus_fact",
      "text": "They are located in the Academic Building D (Room 216). Published office hours are Academic Year: Monday–Friday 8:30 am–4:30 pm; Summer: Monday–Thursday 8:00 am–5:15 pm (closed Fridays).",
      "evidence_ids": [
        "documents:d76a6749-bc33-41bb-b060-6393861f78d9"
      ]
    },
    {
      "kind": "campus_fact",
      "text": "If you are experiencing a mental health emergency during business hours, you may come to D-216 or call the main line at (201) 684-7522 to be connected with the emergency on-call therapist; after hours/weekends call the same main line and follow the prompts. For immediate danger, call 911; you can also call or text 988 (Suicide & Crisis Lifeline) for 24/7 crisis support.",
      "evidence_ids": [
        "documents:058a86ea-11ed-445e-b66f-674ccb69ca65",
        "documents:d76a6749-bc33-41bb-b060-6393861f78d9",
        "contacts:b690fd0c-fc57-492a-a6ad-0d6f4a658df5"
      ]
    }
  ]
}
